draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // brain
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 50*Math.sin(t), H/2, 30, 0, 2*Math.PI);
  ctx.stroke();

  // eyes
  ctx.beginPath();
  ctx.arc(W/2 - 20, H/2 - 20, 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 20, H/2 - 20, 10, 0, 2*Math.PI);
  ctx.stroke();

  // smile
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 20, 20, 0, Math.PI);
  ctx.stroke();

  // psychology insight text
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Human Behavior', W/2, H/2 + 60);
  ctx.fillText('Insight 1142', W/2, H/2 + 90);

  ctx.restore();
}
